/* ===== Drill pack to 100 ===== */
function mkD(id,cat,line,pos,name,focus,players,area,time,int,kit,setup,steps,pts,prog,tm,sc){
  const [work,rest,rounds,sets=1,sr=120]=tm.split('/').map(Number);
  return {id,cat,line,pos,name,focus,players,area,time,int,kit,setup,steps,pts,prog,tm:{work,rest,rounds,sets,sr},sc};
}
